if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#1e3a8a", "#d97706", "#f59e0b", "#3b82f6", "#172554"];
var speedMult = 2.5;
var lineScale = 1.3;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by 'gradation' by 'reona396' ===
// Created as variant #1 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
let shapes = [];
const shapesNum = 5000;
let sMax;

function setup() {
  createCanvas(windowWidth, windowHeight);

  sMax = max(width, height) * 0.3;

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape(i));
  }

  background("#E7ECF2");
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

  background("#E7ECF230");

  noStroke();
  fill(uM_colors[4]);

  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }
}

class Shape {
  constructor(i) {
    this.i = i * 0.01;
    this.A = 0;
    this.B = 0;
    this.S = i % sMax;
  }

  move() {
    this.S += 1;
    if (this.S > sMax) {
      this.S = 0;
    }
  }

  display() {
    this.A = (cos(this.i * 3) - cos(this.i * 6) + 9) * 0.45;
    this.B = this.i / 2 + (sin(this.i * 3) - sin(this.i * 6)) / 3;

    fill(255 * sin(this.B * 10 + (frameCount * speedMult) * 0.1), 100, 150);

    circle(
      this.S * this.A * cos(this.B) + width / 2,
      this.S * this.A * sin(this.B) + height / 2,
      this.S * 0.2 * sin(this.i * 11)
    );
  }
}
